const express = require('express');
const app = express();

// Internal configuration store
const configStore = {
  adminUsers: ['admin@corp.internal'],
  featureFlags: { debugMode: false, maintenanceMode: false },
  rateLimit: { windowMs: 60000, max: 100 }
};

// Middleware to parse incoming config updates
app.use(express.json());

// Type-coercion based access control check
function checkAccessLevel(userLevel, requiredLevel) {
  // userLevel comes from request body, requiredLevel is internal
  // Intended: numeric comparison where higher = more privileged
  if (userLevel >= requiredLevel) {
    return true;
  }
  return false;
}

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

// Get current config (read-only, no auth needed for internal services)
app.get('/api/config', (req, res) => {
  res.json(configStore);
});

// Update configuration - requires access level 9000+
app.post('/api/config/update', (req, res) => {
  const { accessLevel, updates } = req.body;

  if (accessLevel === undefined || updates === undefined) {
    return res.status(400).json({ error: 'Missing accessLevel or updates' });
  }

  // Type confusion vulnerability: if accessLevel is an object or array,
  // JavaScript's >= comparison with a number triggers type coercion.
  // An array like ["9999"] coerces to 9999 via ToPrimitive -> toString -> toNumber
  // But also, an object with valueOf() cannot be passed via JSON...
  // However, an array like [] coerces to 0, and [9999] coerces to 9999
  // The real issue: passing accessLevel as a string "9999" works due to coercion
  // But the deeper bug: passing accessLevel as an array triggers unexpected behavior

  const REQUIRED_LEVEL = 9000;

  if (!checkAccessLevel(accessLevel, REQUIRED_LEVEL)) {
    return res.status(403).json({ error: 'Insufficient access level' });
  }

  // Apply updates with no schema validation - allows prototype pollution path
  if (typeof updates === 'object' && updates !== null) {
    for (const key of Object.keys(updates)) {
      if (key === '__proto__' || key === 'constructor') {
        continue; // basic proto pollution guard
      }
      configStore[key] = updates[key];
    }
  }

  res.json({ success: true, config: configStore });
});

// Admin action endpoint - uses configStore.adminOverride if set
app.post('/api/admin/execute', (req, res) => {
  const { command, user } = req.body;

  // Check if user is admin OR if adminOverride was injected into configStore
  const isAdmin = configStore.adminUsers.includes(user) || configStore.adminOverride === true;

  if (!isAdmin) {
    return res.status(403).json({ error: 'Not an admin' });
  }

  // Simulate command execution for internal tooling
  const result = {
    executed: command,
    timestamp: Date.now(),
    by: user
  };

  res.json(result);
});

// Metrics endpoint for Prometheus scraping
app.get('/metrics', (req, res) => {
  res.set('Content-Type', 'text/plain');
  res.send(`# HELP config_updates_total Total config updates\nconfig_updates_total 0\n`);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Config service listening on port ${PORT}`);
});
